function [re, ve] = gnss_ecef(jd0, te, r, v)
%GNSS_ECEF  The truth (r [m], v [m/s], J2000) at the epoch te [s] of a run that starts at the Julian date jd0, in ECEF.
%   jd0: real[1] (passed a plain number)
%   te: real[1] (passed a plain number)
%   r: real[m][3] (passed in m)
%   v: real[m/s][3] (passed in m/s)
%   returns re: real[m][3] (passed in m)
%   returns ve: real[m/s][3] (passed in m/s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    re = zeros(3, 1);
    ve = zeros(3, 1);
    ce = asils.models.caltime.eci_to_ecef((jd0 + (te / 86400)));
    re = asils.pc.mv(ce, r);
    ve = (asils.pc.mv(ce, v) - asils.pc.cross_([0; 0; 0.00007292115], re));
end
